65	// TestIssueBatchRejectSaveFailureRetrySameState 覆盖题述核心场景：初始
66	// 持有人停用的拒绝落盘失败时返回保存错误、结果为空、请求号不被占用；
67	// 保存恢复后保持原清单重提，重新判断并重新保存该拒绝（这次不算回放），
68	// 只有此后相同内容再次提交才回放已保存的拒绝。
69	func TestIssueBatchRejectSaveFailureRetrySameState(t *testing.T) {
70		r := mustCreate(t, tempDir(t))
71		setupBatchWorld(t, r)
72		if err := r.DeactivateAccount("carol"); err != nil {
73			t.Fatal(err)
74		}
75		req := rejectIssueReq("rb-rej")
76	
77		// 拒绝条件成立（i2 的初始持有人 carol 已停用），但保存这次拒绝失败。
78		blockBatchSave(t, r)
79		res, err := r.IssueBatch(req)
80		assertIssueRejectSaveFailureResult(t, res, err)
81		assertIssueBatchWorldPristine(t, r, req.RequestID)
82	
83		// 保存条件恢复、拒绝条件仍在：原清单重提重新判断并保存此次拒绝，
84		// 保存成功后才返回业务错误本身；这是一次全新判断，不能标回放。
85		restoreBatchSave(t, r)
86		res, err = r.IssueBatch(req)
87		if !errors.Is(err, ErrAccountInactive) {
88			t.Fatalf("重提应在保存成功后返回业务拒绝 ErrAccountInactive: %v", err)
89		}
90		if res.Replayed || res.ItemID != "i2" || !errors.Is(res.Err, ErrAccountInactive) ||
91			len(res.Items) != 0 {
92			t.Fatalf("重提结果异常: %+v", res)
93		}
94		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; !ok {
95			t.Fatal("拒绝保存成功后应登记请求结果")
96		}
97	
98		// 拒绝已保存：此后相同内容再次提交才回放该拒绝。
99		res, err = r.IssueBatch(req)
100		if !errors.Is(err, ErrAccountInactive) || !res.Replayed || res.ItemID != "i2" ||
101			!errors.Is(res.Err, ErrAccountInactive) {
102			t.Fatalf("保存后的再次提交应回放已保存的拒绝: %+v, err %v", res, err)
103		}
104	
105		// 系列从未成功发行，被拒（含那次未保存的失败）不固定版税规则，仍可设置。
106		set := SetRoyaltyRequest{
107			Operator: "alice", Reason: "拒绝后设置版税", RequestID: "rr-freeze-check",
108			SeriesID: "s1", Shares: []RoyaltyShare{{AccountID: "bob", Rate: 500}},
109		}
110		if _, err := r.SetRoyalty(set); err != nil {
111			t.Fatalf("未成功发行的系列不应固定版税规则: %v", err)
112		}
113	}
114	
115	// TestIssueBatchRejectSaveFailureRetryAfterFix 覆盖：未保存的拒绝不占用
116	// 请求号——保存恢复后把停用持有人那一件改为已登记且可用的账户，用同一
117	// 操作者和请求号提交，应按修改后的清单正常发行，不返回请求号冲突，序号
118	// 从 1 连续开始。
119	func TestIssueBatchRejectSaveFailureRetryAfterFix(t *testing.T) {
120		r := mustCreate(t, tempDir(t))
121		setupBatchWorld(t, r)
122		if err := r.RegisterAccount("dave", ""); err != nil {
123			t.Fatal(err)
124		}
125		if err := r.DeactivateAccount("carol"); err != nil {
126			t.Fatal(err)
127		}
128		req := rejectIssueReq("rb-rej-fix")
129	
130		blockBatchSave(t, r)
131		res, err := r.IssueBatch(req)
132		assertIssueRejectSaveFailureResult(t, res, err)
133	
134		// 恢复保存条件，把 i2 的初始持有人改为可用账户 dave；同一操作者与请求号。
135		restoreBatchSave(t, r)
136		fixed := req
137		fixed.Entries = []IssueBatchEntry{be("i1", "bob"), be("i2", "dave")}
138		res, err = r.IssueBatch(fixed)
139		if err != nil {
140			t.Fatalf("修改清单后用原请求号重提应正常发行，不能报请求号冲突: %v", err)
141		}
142		if res.Replayed || res.ItemID != "" || res.Err != nil || len(res.Items) != 2 {
143			t.Fatalf("重提结果异常: %+v", res)
144		}
145		if res.Items[0].ItemID != "i1" || res.Items[0].OwnerID != "bob" ||
146			res.Items[0].Version != 1 || res.Items[0].TxSeq != 1 {
147			t.Fatalf("第一件发行结果异常: %+v", res.Items[0])
148		}
149		if res.Items[1].ItemID != "i2" || res.Items[1].OwnerID != "dave" ||
150			res.Items[1].Version != 1 || res.Items[1].TxSeq != 2 {
151			t.Fatalf("第二件发行结果异常: %+v", res.Items[1])
152		}
153		if r.state.NextSeq != 2 {
154			t.Fatalf("NextSeq = %d, want 2", r.state.NextSeq)
155		}
156		for _, want := range []struct{ item, owner string }{
157			{"i1", "bob"}, {"i2", "dave"},
158		} {
159			h, err := r.GetHolding(want.item)
160			if err != nil || h.OwnerID != want.owner || h.Version != 1 {
161				t.Fatalf("%s 持有异常: %+v, err %v", want.item, h, err)
162			}
163		}
164	
165		// 成功结果保存后，相同内容再提回放首次成功；停用的 carol 与已封存都
166		// 不影响回放内容。
167		replay, err := r.IssueBatch(fixed)
168		if err != nil || !replay.Replayed || len(replay.Items) != 2 {
169			t.Fatalf("成功后重提应回放: %+v, err %v", replay, err)
170		}
171	}
172	
173	// TestIssueBatchRejectSaveFailureAfterReopen 覆盖磁盘视角：保存失败后原
174	// 登记册仍可正常读取——关闭重开看到的仍是拒绝前状态，请求号未占用；
175	// 恢复保存后用原请求重提重新保存拒绝。
176	func TestIssueBatchRejectSaveFailureAfterReopen(t *testing.T) {
177		dir := tempDir(t)
178		r := mustCreate(t, dir)
179		setupBatchWorld(t, r)
180		if err := r.SealSeries("s1", "alice"); err != nil {
181			t.Fatal(err)
182		}
183		req := batchReq("rb-rej-reopen", be("i1", "bob"))
184	
185		blockBatchSave(t, r)
186		res, err := r.IssueBatch(req)
187		assertIssueRejectSaveFailureResult(t, res, err)
188	
189		if err := r.Close(); err != nil {
190			t.Fatal(err)
191		}
192		r2, err := Open(dir)
193		if err != nil {
194			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
195		}
196		t.Cleanup(func() { _ = r2.Close() })
197		if _, err := r2.GetItem("i1"); !errors.Is(err, ErrNotFound) {
198			t.Fatalf("重开后 i1 不应存在: %v", err)
199		}
200		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
201			t.Fatal("重开后未保存的拒绝不应占用请求号")
202		}
203	
204		restoreBatchSave(t, r2)
205		res, err = r2.IssueBatch(req)
206		if !errors.Is(err, ErrSeriesSealed) || res.Replayed || res.Err == nil {
207			t.Fatalf("重开后重提应重新判断并保存封存拒绝: %+v, err %v", res, err)
208		}
209		// 再次提交才回放。
210		res, err = r2.IssueBatch(req)
211		if !errors.Is(err, ErrSeriesSealed) || !res.Replayed {
212			t.Fatalf("再次提交应回放已保存的拒绝: %+v, err %v", res, err)
213		}
214	}
215	
216	// TestIssueBatchRejectSaveFailureOperatorError 覆盖操作者层面的拒绝（无权
217	// 或停用）保存失败时结果不附藏品编号；恢复后重提重新保存并返回原错误。
218	func TestIssueBatchRejectSaveFailureOperatorError(t *testing.T) {
219		r := mustCreate(t, tempDir(t))
220		setupBatchWorld(t, r)
221		// bob 不是系列 s1 的创建账户：ErrForbidden，与具体藏品无关。
222		req := batchReq("rb-rej-op", be("i1", "bob"))
223		req.Operator = "bob"
224	
225		blockBatchSave(t, r)
226		res, err := r.IssueBatch(req)
227		assertIssueRejectSaveFailureResult(t, res, err)
228		if _, ok := r.state.Requests[requestKey("bob", req.RequestID)]; ok {
229			t.Fatal("未保存的拒绝不应占用请求号")
230		}
231	
232		restoreBatchSave(t, r)
233		res, err = r.IssueBatch(req)
234		if !errors.Is(err, ErrForbidden) {
235			t.Fatalf("重提应返回 ErrForbidden: %v", err)
236		}
237		if res.ItemID != "" || res.Replayed || !errors.Is(res.Err, ErrForbidden) {
238			t.Fatalf("操作者层面错误的重提结果异常: %+v", res)
239		}
240		res, err = r.IssueBatch(req)
241		if !errors.Is(err, ErrForbidden) || !res.Replayed {
242			t.Fatalf("再次提交应回放已保存的拒绝: %+v, err %v", res, err)
243		}
244	}
245	
246	// TestIssueBatchRejectSaveFailureIDOccupied 覆盖：编号已占用的拒绝保存
247	// 失败后，未占用的编号不被这次失败占用、历史序号不消耗；恢复后同一请求
248	// 重新保存编号占用拒绝，而清单中原本空闲的编号此刻仍可正常用于另一请求。
249	func TestIssueBatchRejectSaveFailureIDOccupied(t *testing.T) {
250		r := mustCreate(t, tempDir(t))
251		setupBatchWorld(t, r)
252		// i2 已由一次成功的单件发行占用。
253		if _, err := r.Issue(issueReq("i2", "bob")); err != nil {
254			t.Fatal(err)
255		}
256		req := rejectIssueReq("rb-rej-exists")
257	
258		blockBatchSave(t, r)
259		res, err := r.IssueBatch(req)
260		assertIssueRejectSaveFailureResult(t, res, err)
261		if r.state.NextSeq != 1 {
262			t.Fatalf("NextSeq = %d，失败不应消耗历史序号，仍应为 1", r.state.NextSeq)
263		}
264		if _, err := r.GetItem("i1"); !errors.Is(err, ErrNotFound) {
265			t.Fatalf("失败后 i1 不应被登记: %v", err)
266		}
267	
268		restoreBatchSave(t, r)
269		res, err = r.IssueBatch(req)
270		if !errors.Is(err, ErrAlreadyExists) {
271			t.Fatalf("重提应返回 ErrAlreadyExists: %v", err)
272		}
273		if res.Replayed || res.ItemID != "i2" || !errors.Is(res.Err, ErrAlreadyExists) {
274			t.Fatalf("重提结果异常: %+v", res)
275		}
276	
277		// 原清单中未占用的 i1 没有被失败或后来的拒绝占用，可换另一个请求发行。
278		ok := batchReq("rb-i1-now", be("i1", "bob"))
279		if _, err := r.IssueBatch(ok); err != nil {
280			t.Fatalf("未占用编号应仍可发行: %v", err)
281		}
282		if r.state.NextSeq != 2 {
283			t.Fatalf("NextSeq = %d, want 2（原 i2 占 1，新发 i1 占 2）", r.state.NextSeq)
284		}
285	}
286	
287	// TestIssueBatchValidationErrorIgnoresSaveFailure 覆盖：空清单、重复编号、
288	// 必填缺失或引用不存在属于无需保存的参数/对象错误，即使存储暂时不可写，
289	// 也仍返回原错误而不是保存错误，并且不占用请求号。
290	func TestIssueBatchValidationErrorIgnoresSaveFailure(t *testing.T) {
291		r := mustCreate(t, tempDir(t))
292		setupBatchWorld(t, r)
293	
294		blockBatchSave(t, r)
295		defer restoreBatchSave(t, r)
296	
297		// 空清单。
298		if _, err := r.IssueBatch(batchReq("rb-empty")); !errors.Is(err, ErrInvalidArgument) {
299			t.Fatalf("空清单应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
300		}
301		// 清单内编号重复。
302		if _, err := r.IssueBatch(batchReq("rb-dup", be("i1", "bob"), be("i1", "carol"))); !errors.Is(err, ErrInvalidArgument) {
303			t.Fatalf("重复编号应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
304		}
305		// 必填缺失（缺系列）。
306		missing := IssueBatchRequest{
307			Operator: "alice", Reason: "r", RequestID: "rb-missing", BatchNo: "b1",
308			Entries: []IssueBatchEntry{be("i1", "bob")},
309		}
310		if _, err := r.IssueBatch(missing); !errors.Is(err, ErrInvalidArgument) {
311			t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
312		}
313		// 引用对象不存在：未登记的初始持有人，结果指出该件。
314		res, err := r.IssueBatch(batchReq("rb-nf", be("i1", "bob"), be("i2", "ghost")))
315		if !errors.Is(err, ErrNotFound) {
316			t.Fatalf("引用不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
317		}
318		if res.ItemID != "i2" || !errors.Is(res.Err, ErrNotFound) {
319			t.Fatalf("引用不存在的结果异常: %+v", res)
320		}
321		// 操作者未登记。
322		opMissing := batchReq("rb-nf-op", be("i1", "bob"))
323		opMissing.Operator = "nobody"
324		if _, err := r.IssueBatch(opMissing); !errors.Is(err, ErrNotFound) {
325			t.Fatalf("操作者不存在应返回 ErrNotFound: %v", err)
326		}
327	
328		// 无需保存的错误一律不占用请求号，也不消耗历史序号。
329		for _, rid := range []string{"rb-empty", "rb-dup", "rb-missing", "rb-nf", "rb-nf-op"} {
330			if _, ok := r.state.Requests[requestKey("alice", rid)]; ok {
331				t.Fatalf("参数/对象错误不应占用请求号 %s", rid)
332			}
333		}
334		if r.state.NextSeq != 0 {
335			t.Fatalf("NextSeq = %d, want 0", r.state.NextSeq)
336		}
337	}
338	
339	// TestIssueBatchRejectSaveFailureNotCarriedByLaterCommit 覆盖：未保存的
340	// 拒绝在同一已打开登记册上必须彻底撤销——保存条件恢复后另一笔正常操作
341	// 成功落盘时，不能把那次拒绝一起写入。
342	func TestIssueBatchRejectSaveFailureNotCarriedByLaterCommit(t *testing.T) {
343		r := mustCreate(t, tempDir(t))
344		setupBatchWorld(t, r)
345		if err := r.DeactivateAccount("carol"); err != nil {
346			t.Fatal(err)
347		}
348		req := rejectIssueReq("rb-rej-carry")
349	
350		blockBatchSave(t, r)
351		if _, err := r.IssueBatch(req); err == nil {
352			t.Fatal("预期保存失败")
353		}
354	
355		// 保存条件恢复，另一笔完全无关的正常操作成功落盘。
356		restoreBatchSave(t, r)
357		other := batchReq("rb-other", be("i9", "bob"))
358		if _, err := r.IssueBatch(other); err != nil {
359			t.Fatalf("其他正常操作应能成功保存: %v", err)
360		}
361	
362		// 成功落盘的快照中不能夹带那次未保存的拒绝。
363		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
364			t.Fatal("后续成功保存不能把未保存的拒绝一起写入")
365		}
366		if _, err := r.GetItem("i1"); !errors.Is(err, ErrNotFound) {
367			t.Fatalf("i1 不应随其他操作被一起写入: %v", err)
368		}
369	
370		// 原请求号此刻仍可自由使用：状态依旧拒绝时重新保存，成功后才占号。
371		res, err := r.IssueBatch(req)
372		if !errors.Is(err, ErrAccountInactive) || res.Replayed {
373			t.Fatalf("原请求号应仍可使用并重新判断: %+v, err %v", res, err)
374		}
375	}
